"""Prepare requested prompts only; generation and publication remain separate."""
from pathlib import Path
import json
W=Path(__file__).resolve().parent
A=W.parent/'animation-pack-04'
style=json.loads((W/'plan-g3.json').read_text(encoding='utf8'))['jobs'][-1]['prompt'].split('ONE isolated')[0]
def save(root,g,jobs):
    p=root/f'plan-g{g}.json'
    if p.exists():raise FileExistsError(p)
    p.write_text(json.dumps({'generator':'built-in image_gen','jobs':jobs},ensure_ascii=False,indent=2),encoding='utf8')
def obj(id,description,g,size=(512,512),height=300,kind='object'):
    return dict(id=id,group=g,kind=kind,canvas=list(size),height=height,alpha=True,prompt=style+' ONE isolated complete side-view game asset: '+description+'. True transparent alpha, crisp readable silhouette, whole object visible, no terrain slab, no ellipse shadow, no text except any explicitly requested single letter. Object rests at bottom of canvas. Keep painterly gold highlights and teal shadows consistent with reference.')
save(W,6,[obj('cudo-sokolovo-pero','grey-white falcon feather, one clear water droplet at the tip',6,height=320),obj('cudo-prelomljeno-koplje','Marko\'s broken wooden spear, three splintered pieces tied together with a leather belt, iron spearhead visible',6,height=320)])
breakables=[('kosnica','woven beehive on a stump'),('plast','small haystack tied with rope'),('tikve','compact pile of gourds and pumpkins'),('stena-napukla','large cracked rock, clear deep fractures'),('panj','rotting tree stump with mushrooms'),('crkveni-sanduk','ironbound monastery chest with books and an Orthodox cross'),('bure-baruta','gunpowder oak barrel with fuse and Ottoman crescent seal, NO Christian cross'),('tobolac','woven basket full of arrows'),('santa','angular chunk of blue-white ice'),('vagon','small medieval mining cart with iron wheels filled with ore')]
jobs=[obj('razbi-'+id,d,7,(1024,1024),400) for id,d in breakables]
for id,char in [('m','М'),('a','А'),('r','Р'),('k','К'),('o','О')]:
    jobs.append(obj('predmet-slovo-'+id,'one round gold medallion, engraved central LARGE single Cyrillic letter "'+char+'". Render EXACTLY this one character, bold readable at tiny scale, no other writing',7))
collect=[('zapis','rolled parchment tied with a red wax seal'),('srce-deo','one quarter of a golden heart, clearly part of a four-piece heart'),('kljuc','old iron key tied with red ribbon'),('moc-oganj','spherical fire power orb, orange flame enclosed in glowing glass'),('moc-grom','spherical lightning power orb, bright gold branching lightning enclosed in dark blue glass'),('moc-vila','spherical turquoise fairy power orb, delicate wing-shaped light enclosed in teal glass'),('trava','tied bundle of medicinal herbs'),('cutura','wooden wine gourd with stopper and leather strap')]
jobs += [obj('predmet-'+id,d,7) for id,d in collect]
puzzles=[('ploca-pritisak','raised stone pressure plate on a low base, side view',(512,256),100),('ploca-pritisak-stisnuta','SAME stone pressure plate pressed down flush into the base, matching reference footprint and baseline',(512,256),100),('teret-sanduk','very heavy reinforced wooden crate with large iron bands, pushable puzzle weight',(1024,1024),450),('pod-napukao','wide shallow stone floor slab with deep central cracks',(512,256),100),('zid-napukao','ONLY branching dark cracks as a transparent overlay for a stone wall; no stone panel and no solid background',(512,512),480),('lift-platforma','wide timber lift platform reinforced with iron, two chains going vertically upward at its ends',(1024,512),480),('kotur','wooden pulley wheel with a hanging iron chain',(512,512),400),('splav','wide raft made from lashed logs, clear side view',(1024,512),230),('kolje','seamlessly repeating horizontal row of sharpened timber stakes, equal height and spacing, no end posts',(512,192),180),('siljci','seamlessly repeating horizontal row of iron spikes on a low rail, equal height and spacing, no end posts',(512,192),180),('vrata-zakljucana','closed ironbound medieval double wooden door in a stone frame, large iron padlock visible',(1024,1024),850),('vrata-otkljucana','SAME doorway and ironbound double wooden doors swung open, padlock released, transparent opening, matching frame silhouette and baseline',(1024,1024),850)]
for id,d,size,h in puzzles:
    j=obj(id,d,7,size,h)
    if id=='zid-napukao':j['kind']='overlay'
    if id in ['kolje','siljci']:j['kind']='repeat-row'
    if id=='ploca-pritisak-stisnuta':j['reference']='art/world-pack-03/ploca-pritisak.png'
    if id=='vrata-otkljucana':j['reference']='art/world-pack-03/vrata-zakljucana.png'
    jobs.append(j)
save(W,7,jobs)
def clip(id,who,n,loop,description,g):
    cols=5 if n==5 else 4 if n==8 else 3 if n==6 else 2
    rows=(n+cols-1)//cols
    return dict(id=id,group=g,who=who,frames=n,loop=loop,fps=12,cols=cols,rows=rows,cell=[512,512],extra=0,reference=f'art/animation-pack-03/sources/{who}-idle/base-source.png',prompt=f'EXACTLY {n} full-body animation poses in {cols} columns and {rows} rows, read left to right then down. Invisible equal square slots, no grid or labels. Pure flat #00FF00 green empty background. Same exact character identity, costume, weapons, anatomy and head size as supplied reference. Painterly cel shaded game art. Facing RIGHT, far limbs darker, entire pose fits in its own cell with green gutters. Shared grounded foot baseline, fixed anatomical scale, no camera movement, no ground shadows. '+description)
save(A,6,[clip('marko-slide','marko',6,False,'1 crouch; 2 drop onto hip; 3 side slide with boots extended forward; 4 low sliding extension; 5 tuck knees and brace; 6 stand. Mace held securely, no obstacle drawn.',6),clip('marko-hang','marko',6,True,'Continuous loop hanging by ONE hand above head, body fully below hand, legs sway left then right and back. Hand stays at same top anchor. Do NOT draw ledge or platform.',6),clip('sword-climb','sword',6,True,'Janissary climbing ladder, three-quarter rear view, saber SHEATHED on belt. Alternate near arm high then far arm high, opposite knee lifts, smooth repeating 6-phase climb. NO ladder drawn.',6)])
spec=[('marko-combo-4','marko',8,False,'Overhead finisher: 1 guard; 2 step; 3 mace winds behind head; 4 raised highest; 5 explosive downward strike with forward shoulder bash CONTACT; 6 follow through; 7 recoil; 8 guard.'),('marko-air-1','marko',5,False,'Airborne horizontal mace strike: 1 tucked jump guard; 2 wind back; 3 horizontal CONTACT to right; 4 follow through; 5 airborne recovery. No floor.'),('marko-air-2','marko',5,False,'Second aerial strike rising from below: 1 airborne mace low; 2 twist; 3 rising diagonal CONTACT; 4 mace high; 5 airborne recovery.'),('marko-uppercut','marko',6,False,'1 crouch; 2 mace low behind; 3 drive up with legs; 4 upward mace CONTACT; 5 fully extended rising body; 6 recovery.'),('marko-dash-strike','marko',6,False,'Low rushing mace thrust: 1 crouch; 2 coil; 3 push off; 4 mace extended forward CONTACT; 5 low follow through; 6 recovery. Small attached dust behind boots, no detached effect clouds.'),('marko-charge-hold','marko',4,True,'Tense charge hold looping: mace behind shoulder glows gold, subtle breath and weight shift through four unique poses, return smoothly to first. Glow tightly attached to mace.'),('marko-push','marko',6,True,'Loop pushing heavy crate with shoulder: brace bent torso forward, arms forward, six alternating walking effort phases. NO crate drawn; game draws it separately. Fixed root, real alternating legs.'),('marko-lever','marko',6,False,'1 reach forward; 2 grasp invisible lever; 3 brace; 4 pull down and back; 5 full pull; 6 release. NO lever drawn; game draws it separately.'),('shield-guardbreak','shield',4,False,'1 shield guard; 2 impact forces shield to outside; 3 stagger backward, guard wide open; 4 vulnerable recovery, same shield held.'),('oklopnik-armorbreak','oklopnik',4,False,'1 armored guard; 2 armor hit; 3 breastplate cracks with a few nearby flying armor pieces inside cell; 4 exposed stagger. Keep face and body identity.'),('akindzija-backstep','akindzija',4,False,'Backwards evade while FACING RIGHT: 1 tense guard; 2 plant front boot; 3 low backwards hop with back knee reaching left; 4 land in guard. No mirrored facing.'),('palikuca-burn','palikuca',6,True,'Loop panicking from own torch fire: attached orange flames on sleeves, alternately wave arms and stomp feet, recoiling from heat. Same actor and torch identity; no ground flame patch.')]
save(A,7,[clip(id,who,n,loop,d,7) for id,who,n,loop,d in spec])
print('Prepared prompts only: group 6, group 7. No images claimed.')
